import type OpenFin from '@openfin/core';

import { isEnterpriseBrowser } from '@common/utils/enterpriseBrowser';
import { createLogger } from '@common/utils/logger';

const logger = createLogger('common.tabs');

export interface TabsHandler {
    /**
     * Shows tabs for specified window instance. Does nothing if tabs are visible.
     */
    show(): Promise<void>;

    /**
     * Hides tabs for specified window instance. Does nothing if tabs are hidden.
     */
    hide(layoutOverrides?: OpenFin.LayoutOptions): Promise<void>;

    /**
     * Checks if the tabs for specified window are visible and resolves with true/false.
     */
    isShowingTabs(): Promise<boolean>;
}

export const getTabsHandler = (layoutIdentity: OpenFin.LayoutIdentity): TabsHandler => {
    const layout = fin.Platform.Layout.wrapSync(layoutIdentity);
    return {
        show: async () => {
            const layoutConfig = await layout.getConfig();
            const { settings, dimensions } = layoutConfig;
            const isEnterprise = await isEnterpriseBrowser(layoutIdentity);

            await layout.replace({
                ...layoutConfig,
                settings: {
                    ...settings,
                    hasHeaders: true,
                    reorderEnabled: true
                },
                dimensions: {
                    ...dimensions,
                    headerHeight: isEnterprise ? 28 : 30
                }
            });
        },
        hide: async (layoutOverrides?: OpenFin.LayoutOptions) => {
            const layoutConfig = await layout.getConfig();
            const { settings, dimensions } = await layoutConfig;
            await layout.replace({
                ...layoutConfig,
                settings: {
                    ...settings,
                    hasHeaders: false,
                    reorderEnabled: layoutOverrides?.settings?.reorderEnabled ?? false
                },
                dimensions: {
                    ...dimensions,
                    headerHeight: 0
                }
            });
        },
        isShowingTabs: async () => {
            try {
                const layoutConfig = await layout.getConfig();
                const { settings } = await layoutConfig;

                return settings.hasHeaders;
            } catch (err) {
                logger.error('isVisible', 'Failed to get layout config', {
                    error: err instanceof Error ? err.message : String(err)
                });
                return true;
            }
        }
    };
};
